/* ============================================================
   error-reporter.js
   Auto-mounting client-side error capture.

   Captures:
     - Uncaught JS errors (window.onerror)
     - Unhandled promise rejections
     - Manual reports via window.__dukanReport(...)
     - (Opt-in) failed fetch() — wrap with __dukanWatchFetch

   Sends to /api/log-error endpoint (fire-and-forget POST).

   PRIVACY:
     - Never sends form values, localStorage, cookies, or DOM content
     - Server hashes IP daily; no PII stored
     - Throttled client-side (max 10 reports / 60s)
     - Deduped within 5 min on the server side

   USAGE:
     <script src="/assets/js/error-reporter.js" defer></script>
     // That's it. Auto-mounts on load.
   ============================================================ */

(function () {
  'use strict';

  // -------- Config --------
  var ENDPOINT       = '/api/log-error';
  var MAX_PER_MINUTE = 10;
  var STORAGE_KEY    = 'dl_err_session_v1';

  // -------- Session id (no PII) --------
  var sessionId;
  try {
    sessionId = sessionStorage.getItem(STORAGE_KEY);
    if (!sessionId) {
      sessionId = 'sess_' + Math.random().toString(36).slice(2) + '_' +
                  Date.now().toString(36);
      sessionStorage.setItem(STORAGE_KEY, sessionId);
    }
  } catch (e) {
    sessionId = 'sess_anon';
  }

  // -------- Throttle window --------
  var recentSent = [];

  function withinRateLimit() {
    var now = Date.now();
    recentSent = recentSent.filter(function (t) { return now - t < 60000; });
    if (recentSent.length >= MAX_PER_MINUTE) return false;
    recentSent.push(now);
    return true;
  }

  // -------- Auth header (if logged in via Supabase) --------
  function authHeader() {
    try {
      // Supabase persists session in localStorage under 'sb-*'
      var keys = Object.keys(localStorage);
      for (var i = 0; i < keys.length; i++) {
        if (keys[i].indexOf('sb-') === 0 && keys[i].indexOf('-auth-token') > 0) {
          var raw = localStorage.getItem(keys[i]);
          if (!raw) continue;
          try {
            var obj = JSON.parse(raw);
            var token = obj && obj.access_token;
            if (token) return 'Bearer ' + token;
          } catch (_) {}
        }
      }
    } catch (_) {}
    return null;
  }

  // -------- Send a report --------
  function send(payload) {
    if (!withinRateLimit()) return;
    try {
      var body = {
        source:      payload.source || 'js',
        severity:    payload.severity || 'error',
        error_msg:   String(payload.message || '').slice(0, 1000),
        error_stack: String(payload.stack || '').slice(0, 4000),
        page_url:    String(location.href).slice(0, 500),
        session_id:  sessionId,
        referrer:    String(document.referrer || '').slice(0, 200),
        line:        payload.line,
        col:         payload.col
      };
      var headers = { 'Content-Type': 'application/json' };
      var ah = authHeader();
      if (ah) headers['Authorization'] = ah;

      // Use keepalive so the report flushes even when navigating away
      if (typeof fetch === 'function') {
        fetch(ENDPOINT, {
          method:    'POST',
          headers:   headers,
          body:      JSON.stringify(body),
          keepalive: true,
          credentials: 'omit'
        }).catch(function () { /* silent */ });
      } else if (navigator.sendBeacon) {
        navigator.sendBeacon(
          ENDPOINT,
          new Blob([JSON.stringify(body)], { type: 'application/json' })
        );
      }
    } catch (e) {
      // The reporter itself must never throw
    }
  }

  // -------- 1. window.onerror --------
  var prevOnError = window.onerror;
  window.onerror = function (msg, src, line, col, err) {
    try {
      // Skip CORS-blocked "Script error." which contains no useful info
      if (msg === 'Script error.' && !src) return false;
      send({
        message: String(msg || ''),
        stack:   err && err.stack ? String(err.stack) : '',
        line:    line,
        col:     col,
        source:  'js',
        severity:'error'
      });
    } catch (_) {}
    if (typeof prevOnError === 'function') {
      try { return prevOnError.apply(this, arguments); } catch (_) {}
    }
    return false;
  };

  // -------- 2. Unhandled promise rejections --------
  window.addEventListener('unhandledrejection', function (ev) {
    try {
      var reason = ev && ev.reason;
      var msg = '';
      var stk = '';
      if (reason instanceof Error) {
        msg = reason.message || String(reason);
        stk = reason.stack || '';
      } else if (typeof reason === 'string') {
        msg = reason;
      } else {
        try { msg = JSON.stringify(reason); } catch (_) { msg = String(reason); }
      }
      send({
        message:  'unhandledrejection: ' + msg,
        stack:    stk,
        source:   'promise',
        severity: 'error'
      });
    } catch (_) {}
  });

  // -------- 3. Optional: wrap fetch to detect failed calls --------
  // Off by default — set window.__dukanWatchFetch = true BEFORE this
  // script loads to enable.
  if (window.__dukanWatchFetch && typeof window.fetch === 'function') {
    var origFetch = window.fetch.bind(window);
    window.fetch = function (input, init) {
      var url = (typeof input === 'string') ? input :
                (input && input.url) || '<unknown>';
      return origFetch(input, init).then(function (resp) {
        if (!resp.ok && resp.status >= 500) {
          send({
            message:  'fetch ' + resp.status + ' ' + url,
            source:   'fetch',
            severity: resp.status >= 500 ? 'error' : 'warn'
          });
        }
        return resp;
      }).catch(function (e) {
        send({
          message:  'fetch failed: ' + url + ' — ' + (e && e.message ? e.message : e),
          stack:    e && e.stack ? String(e.stack) : '',
          source:   'fetch',
          severity: 'error'
        });
        throw e;
      });
    };
  }

  // -------- 4. Public manual reporter --------
  window.__dukanReport = function (message, opts) {
    opts = opts || {};
    send({
      message:  String(message || 'manual report'),
      stack:    opts.stack || (new Error()).stack,
      source:   opts.source || 'js',
      severity: opts.severity || 'warn'
    });
  };
})();
;

/* ---- photo-fit.js (bdd15f0553) ---- */
/* ============================================================
   photo-fit.js — Adaptive object-fit for shop photos
   ============================================================
   PROBLEM: Owners upload photos in mixed aspect ratios (tall posters,
   wide facades, square IG-style). Cards use object-fit:cover which
   crops tall photos awkwardly — logos, signboards, faces get cut.

   SOLUTION: Detect each image's natural aspect ratio after load.
   - Tall portraits (ratio < 0.78) → switch to object-fit:contain
     with a soft cream gradient background so the FULL photo shows
     (letterboxed) instead of being cropped.
   - Everything else → keep object-fit:cover (default, works fine).

   FEATURES:
   - Universal: scans all <img> on the page after DOM ready.
   - Reactive: MutationObserver catches dynamically added images
     (e.g. cards loaded via async fetch).
   - Idempotent: each image processed once via data-fit-checked.
   - Robust: ignores images that aren't displayed in containers
     (icons, logos, decorative bg).

   ZERO RISK: only sets inline styles on <img> elements. Doesn't
   touch IDs, classes, handlers, or DB. Disable by removing the
   <script> include or by adding data-fit-skip="1" to an <img>.
============================================================ */
(function(){
  'use strict';

  // Portrait threshold — if image naturalWidth/naturalHeight < this,
  // we treat it as "tall" and switch to contain.
  // 0.78 ≈ slightly taller than 4:5 IG portrait.
  // Adjust higher to be more aggressive (more images get contain'd).
  var PORTRAIT_THRESHOLD = 0.78;

  // Soft branded background applied behind contained images
  var CONTAIN_BG = 'linear-gradient(135deg, #FFF7ED, #FFEDD5)';

  // Skip very small images (icons, logos, avatars under this size)
  var MIN_DISPLAY_SIZE_PX = 100;

  function processImg(img){
    if (img.dataset.fitChecked) return;
    if (img.dataset.fitSkip) return;

    var handle = function(){
      try {
        if (!img.naturalWidth || !img.naturalHeight) return;

        // Skip tiny decorative images
        var rect = img.getBoundingClientRect();
        if (rect.width < MIN_DISPLAY_SIZE_PX && rect.height < MIN_DISPLAY_SIZE_PX) return;

        var naturalRatio = img.naturalWidth / img.naturalHeight;

        if (naturalRatio < PORTRAIT_THRESHOLD){
          // Tall portrait — show full image with soft background
          img.style.objectFit = 'contain';

          // Set background on the IMG's parent if it's a "photo container"
          // (heuristic: parent has aspect-ratio defined OR has overflow:hidden)
          var parent = img.parentElement;
          if (parent){
            var cs = window.getComputedStyle(parent);
            var looksLikePhotoBox = (
              cs.aspectRatio !== 'auto' ||
              cs.overflow === 'hidden' ||
              parent.style.background === '' &&
                (cs.backgroundColor === 'rgba(0, 0, 0, 0)' || cs.backgroundColor === 'transparent')
            );
            if (looksLikePhotoBox && !parent.dataset.fitBgSet){
              // Only set if parent doesn't already have a strong background
              var existingBg = parent.style.background || cs.backgroundImage;
              if (!existingBg || existingBg === 'none'){
                parent.style.background = CONTAIN_BG;
                parent.dataset.fitBgSet = '1';
              }
            }
          }

          img.dataset.fitMode = 'contain';
        } else {
          // Landscape or square — cover is fine (default)
          img.dataset.fitMode = 'cover';
        }
      } catch(_){}
      img.dataset.fitChecked = '1';
    };

    if (img.complete && img.naturalWidth){
      handle();
    } else {
      img.addEventListener('load', handle, { once: true });
      // Also handle error gracefully (don't try forever)
      img.addEventListener('error', function(){ img.dataset.fitChecked = '1'; }, { once: true });
    }
  }

  function processAll(root){
    (root || document).querySelectorAll('img').forEach(processImg);
  }

  // Initial pass
  if (document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', function(){ processAll(); });
  } else {
    processAll();
  }

  // Watch for dynamically added images (cards loaded via fetch, infinite scroll, etc.)
  var observer = new MutationObserver(function(mutations){
    mutations.forEach(function(m){
      m.addedNodes.forEach(function(node){
        if (node.nodeType !== 1) return;
        if (node.tagName === 'IMG'){
          processImg(node);
        } else if (node.querySelectorAll){
          node.querySelectorAll('img').forEach(processImg);
        }
      });
    });
  });

  // Wait for body
  function startObserver(){
    if (document.body){
      observer.observe(document.body, { childList: true, subtree: true });
    } else {
      setTimeout(startObserver, 50);
    }
  }
  startObserver();

  // Public API (optional usage from console / other scripts)
  window.DukanPhotoFit = {
    rescan: processAll,
    threshold: PORTRAIT_THRESHOLD,
    setThreshold: function(t){ PORTRAIT_THRESHOLD = t; }
  };
})();
;

/* ---- nav.js (a427f98b8d) ---- */
// =====================================================
// nav.js — Auto-inject hamburger menu + mobile nav drawer
// =====================================================
// Self-initializing on DOMContentLoaded.
// Detects .topbar-inner and adds hamburger + backdrop.
// Works on all pages that have <header class="topbar">.
// =====================================================

(function(){
  // ===== Shortlist counter pill — injected into .nav-links on every page =====
  function injectShortlistLink(navLinks){
    if (!navLinks) return;
    if (navLinks.querySelector('.nav-shortlist-pill')) return; // avoid double
    const a = document.createElement('a');
    a.href = '/shortlist.html';
    a.className = 'nav-shortlist-pill';
    a.setAttribute('title', 'My saved shops');
    a.innerHTML = '<span aria-hidden="true">❤️</span>'
      + '<span class="nsp-label">Shortlist</span>'
      + '<span class="nsp-count" id="navShortlistCount" style="display:none">0</span>';
    a.style.cssText = 'display:inline-flex;align-items:center;gap:6px;background:#FEF2F2;color:#991B1B;border:1px solid #FECACA;padding:6px 12px;border-radius:99px;font-size:.82rem;font-weight:700;text-decoration:none;transition:.15s;font-family:inherit';
    a.onmouseover = function(){ this.style.background = '#FEE2E2'; this.style.transform = 'translateY(-1px)'; };
    a.onmouseout  = function(){ this.style.background = '#FEF2F2'; this.style.transform = ''; };
    navLinks.appendChild(a);

    // Inject CSS for count badge
    if (!document.getElementById('nav-shortlist-css')){
      const s = document.createElement('style');
      s.id = 'nav-shortlist-css';
      s.textContent = '.nsp-count{ background:#DC2626; color:#fff; font-size:.66rem; font-weight:800; padding:1px 7px; border-radius:99px; letter-spacing:.02em; min-width:18px; text-align:center; line-height:1.4 }'
        + '@media (max-width:520px){'
        /* Hide the word "Shortlist" only while the pill is squeezed into the
           collapsed topbar. Inside the OPEN drawer there is a full row of
           space, and hiding it there left a wide bar showing just a heart. */
        + '  .nav-links:not(.open) .nav-shortlist-pill .nsp-label{ display:none }'
        + '  .nav-links:not(.open) .nav-shortlist-pill{ padding:6px 10px !important }'
        + '}';
      document.head.appendChild(s);
    }

    function updateCount(){
      if (typeof DukanShortlist === 'undefined') { setTimeout(updateCount, 200); return; }
      const n = DukanShortlist.count();
      const el = document.getElementById('navShortlistCount');
      if (!el) return;
      if (n > 0){ el.textContent = n; el.style.display = ''; }
      else { el.style.display = 'none'; }
    }
    updateCount();
    // Subscribe to changes
    if (typeof DukanShortlist !== 'undefined'){
      try { DukanShortlist.onChange(updateCount); } catch(_){}
    } else {
      // Shortlist script may load after nav.js; poll briefly
      let tries = 0;
      const t = setInterval(function(){
        if (typeof DukanShortlist !== 'undefined' || tries++ > 25){
          clearInterval(t);
          try { DukanShortlist && DukanShortlist.onChange(updateCount); } catch(_){}
          updateCount();
        }
      }, 200);
    }
  }

  function init(){
    const topbarInner = document.querySelector('.topbar-inner');
    if (!topbarInner) return;
    const navLinks = topbarInner.querySelector('.nav-links');
    if (!navLinks) return;

    // Inject shortlist pill into nav (every page that has .nav-links)
    injectShortlistLink(navLinks);

    // Avoid double-injection (in case script loads twice)
    if (topbarInner.querySelector('.hamburger')) return;

    // Create hamburger button
    const hamburger = document.createElement('button');
    hamburger.className = 'hamburger';
    hamburger.setAttribute('aria-label', 'Toggle menu');
    hamburger.setAttribute('aria-expanded', 'false');
    hamburger.innerHTML = '<span class="hamburger-icon"><span></span><span></span><span></span></span>';

    // Insert hamburger before nav-links
    topbarInner.insertBefore(hamburger, navLinks);

    // Create backdrop
    const backdrop = document.createElement('div');
    backdrop.className = 'nav-backdrop';
    document.body.appendChild(backdrop);

    // Toggle handlers
    function toggleMenu(){
      const isOpen = navLinks.classList.toggle('open');
      hamburger.classList.toggle('open', isOpen);
      backdrop.classList.toggle('show', isOpen);
      hamburger.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
      document.body.style.overflow = isOpen ? 'hidden' : '';
    }
    function closeMenu(){
      navLinks.classList.remove('open');
      hamburger.classList.remove('open');
      backdrop.classList.remove('show');
      hamburger.setAttribute('aria-expanded', 'false');
      document.body.style.overflow = '';
    }

    hamburger.addEventListener('click', toggleMenu);
    backdrop.addEventListener('click', closeMenu);

    // Close on link click (mobile UX)
    navLinks.querySelectorAll('a').forEach(a => {
      a.addEventListener('click', () => {
        // Small delay so click registers
        setTimeout(closeMenu, 100);
      });
    });

    // Close on Escape key
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && navLinks.classList.contains('open')) closeMenu();
    });

    // Close on resize > tablet breakpoint
    window.addEventListener('resize', () => {
      if (window.innerWidth > 720) closeMenu();
    });
  }

  if (document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

  // ============================================================
  // v219: Offline banner — panel pages previously showed a blank
  // half-rendered screen on 2G dropouts with no message at all.
  // Every page that loads nav.js now gets this for free.
  // ============================================================
  (function netBanner(){
    var el = null;
    function show(){
      if (el) return;
      el = document.createElement('div');
      el.id = 'dlNetBanner';
      el.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:99999;background:#B91C1C;color:#fff;text-align:center;padding:9px 14px;font-size:.85rem;font-weight:700;font-family:inherit;box-shadow:0 2px 10px rgba(0,0,0,.25)';
      el.innerHTML = '📡 Internet नहीं चल रहा — connection आते ही अपने-आप ठीक हो जाएगा। / No internet — will recover automatically.';
      document.body.appendChild(el);
    }
    function hide(){
      if (!el) return;
      el.style.background = '#15803D';
      el.innerHTML = '✓ Internet वापस आ गया! / Back online.';
      setTimeout(function(){ if (el){ el.remove(); el = null; } }, 2000);
    }
    window.addEventListener('offline', show);
    window.addEventListener('online', hide);
    if (navigator.onLine === false) show();
  })();
})();
;

/* ---- pwa.js (60d98cd52e) ---- */
/* ============================================================
   pwa.js — Service-Worker registration + install banner
   Loaded on public pages: index, business, browse, search
   ============================================================ */
(function () {
  'use strict';

  // ---- Service Worker registration ----
  if ('serviceWorker' in navigator) {
    window.addEventListener('load', function () {
      navigator.serviceWorker.register('/sw.js', { scope: '/' }).catch(function (err) {
        console.warn('SW registration failed:', err);
      });
    });
  }

  // ---- Install banner (mobile-first, dismissible) ----
  var DISMISS_KEY = 'dukan_pwa_dismissed_at';
  var DISMISS_DAYS = 7;
  var deferredPrompt = null;

  function isStandalone() {
    return (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches)
      || window.navigator.standalone === true;
  }

  function recentlyDismissed() {
    try {
      var ts = parseInt(localStorage.getItem(DISMISS_KEY) || '0', 10);
      if (!ts) return false;
      var ageMs = Date.now() - ts;
      return ageMs < DISMISS_DAYS * 24 * 60 * 60 * 1000;
    } catch (e) {
      return false;
    }
  }

  function isMobileLike() {
    var ua = (navigator.userAgent || '').toLowerCase();
    if (/android|iphone|ipod|ipad|mobile/.test(ua)) return true;
    return Math.min(window.innerWidth, window.innerHeight) <= 820;
  }

  function buildBanner(showInstallBtn) {
    if (document.getElementById('pwaBanner')) return null;
    var banner = document.createElement('div');
    banner.id = 'pwaBanner';
    banner.setAttribute('role', 'dialog');
    banner.setAttribute('aria-label', 'Install DukanList app');
    banner.style.cssText = [
      'position:fixed',
      'left:12px',
      'right:12px',
      'bottom:max(12px, env(safe-area-inset-bottom))',
      'background:#fff',
      'border:1px solid #E5E7EB',
      'border-radius:14px',
      'box-shadow:0 10px 30px rgba(15,23,42,.18)',
      'padding:12px 14px',
      'z-index:9998',
      'display:flex',
      'align-items:center',
      'gap:12px',
      'font-family:Inter,sans-serif',
      'transform:translateY(120%)',
      'opacity:0',
      'transition:transform .35s ease, opacity .35s ease',
      'max-width:520px',
      'margin:0 auto'
    ].join(';');
    banner.innerHTML =
      '<div style="font-size:1.6rem;line-height:1;flex-shrink:0">📱</div>' +
      '<div style="flex:1;min-width:0">' +
        '<div style="font-weight:800;font-size:.92rem;color:#0B1220;line-height:1.25">Install DukanList app</div>' +
        '<div style="font-size:.78rem;color:#6B7280;margin-top:2px;line-height:1.35">One-tap access — works offline. ' + (showInstallBtn ? '' : 'Tap browser menu → "Add to Home Screen".') + '</div>' +
      '</div>' +
      (showInstallBtn
        ? '<button id="pwaInstallBtn" style="background:linear-gradient(135deg,#FF6B1A,#E55100);color:#fff;border:none;padding:9px 14px;border-radius:9px;font-weight:800;font-size:.85rem;cursor:pointer;font-family:inherit;min-height:38px;white-space:nowrap">Install</button>'
        : '') +
      '<button id="pwaCloseBtn" aria-label="Dismiss" style="background:transparent;border:none;color:#6B7280;font-size:1.3rem;cursor:pointer;padding:4px 6px;line-height:1;font-family:inherit">&times;</button>';
    document.body.appendChild(banner);
    // Slide in
    requestAnimationFrame(function () {
      banner.style.transform = 'translateY(0)';
      banner.style.opacity = '1';
    });
    return banner;
  }

  function dismissBanner() {
    var banner = document.getElementById('pwaBanner');
    if (!banner) return;
    banner.style.transform = 'translateY(120%)';
    banner.style.opacity = '0';
    setTimeout(function () { if (banner.parentNode) banner.parentNode.removeChild(banner); }, 350);
    try { localStorage.setItem(DISMISS_KEY, String(Date.now())); } catch (e) {}
  }

  function wireBanner(banner) {
    if (!banner) return;
    var closeBtn = document.getElementById('pwaCloseBtn');
    if (closeBtn) closeBtn.addEventListener('click', dismissBanner);
    var installBtn = document.getElementById('pwaInstallBtn');
    if (installBtn) {
      installBtn.addEventListener('click', async function () {
        if (!deferredPrompt) {
          dismissBanner();
          return;
        }
        try {
          deferredPrompt.prompt();
          var choice = await deferredPrompt.userChoice;
          if (choice && choice.outcome === 'accepted') {
            dismissBanner();
          } else {
            dismissBanner();
          }
        } catch (e) {
          console.warn('Install prompt failed:', e);
          dismissBanner();
        }
        deferredPrompt = null;
      });
    }
  }

  function maybeShowBanner() {
    if (isStandalone()) return;
    if (recentlyDismissed()) return;
    if (!isMobileLike()) return;
    // Show after 2.5s so the banner doesn't interrupt initial paint
    setTimeout(function () {
      if (isStandalone() || recentlyDismissed()) return;
      var banner = buildBanner(!!deferredPrompt);
      wireBanner(banner);
    }, 2500);
  }

  // beforeinstallprompt may fire even after our timer — handle both orders
  window.addEventListener('beforeinstallprompt', function (e) {
    e.preventDefault();
    deferredPrompt = e;
    // If a banner is already shown without Install btn, re-build with it
    var existing = document.getElementById('pwaBanner');
    if (existing) {
      existing.parentNode.removeChild(existing);
      if (!recentlyDismissed() && !isStandalone()) {
        var banner = buildBanner(true);
        wireBanner(banner);
      }
    }
  });

  window.addEventListener('appinstalled', function () {
    try { localStorage.setItem(DISMISS_KEY, String(Date.now())); } catch (e) {}
    dismissBanner();
    deferredPrompt = null;
  });

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', maybeShowBanner);
  } else {
    maybeShowBanner();
  }
})();
;

/* ---- dl-city-cleanup.js (c1b5f54181) ---- */
/* DL CITY CLEANUP (2026-09 v23)
   --------------------------------
   Left over from the "Golden Pages of Dabwali" phase, when the site was
   deliberately narrowed to one town.

   v23 — city dropdowns are no longer locked.
   v22 selected Mandi Dabwali and then set display:none + disabled on every
   other city option, on search, browse, discover and the register form. The
   site has since reopened to Sirsa, Bathinda, Mansa and Muktsar — the footer
   and the Pulse card say so, and there are live listings in Bathinda and
   Sangat — so this was stopping customers from filtering to a Punjab town and
   stopping those shopkeepers from registering. Dabwali is still pre-selected
   as a sensible default; nothing is hidden or disabled any more.

   STILL ACTIVE (cosmetic, from the same phase — review when convenient):
     * nukeCityText()   strips "Sirsa · Bathinda · Mansa · Muktsar" runs out of
                        visible text
     * hideBizLocation() hides the city/area chip on a listing page
*/
(function(){
  'use strict';
  var TAG = '[dl-city]';

  // 1. Pre-select Mandi Dabwali on any city dropdown — as a DEFAULT only.
  //    Nothing is hidden and nothing is disabled: the other towns have to stay
  //    reachable or neither customers nor shopkeepers can leave Dabwali.
  //    Runs once, and never overrides a choice the visitor has already made.
  var citySelectsSeeded = [];
  function forceCityDabwali(){
    var selects = document.querySelectorAll('select#cityId, select#citySelect, select[name="city"]');
    for (var i = 0; i < selects.length; i++){
      var sel = selects[i];
      if (citySelectsSeeded.indexOf(sel) !== -1) continue;   // already defaulted
      if (sel.options.length < 2) continue;                  // not populated yet
      citySelectsSeeded.push(sel);
      if (sel.value) continue;                               // visitor already chose
      if (window.DukanCity && DukanCity.chosen()) continue; // v278: picked 'all' on purpose — leave it blank
      var opts = sel.options;
      for (var j = 0; j < opts.length; j++){
        var v = (opts[j].value || '').toLowerCase();
        var t = (opts[j].textContent || '').toLowerCase();
        if (v.indexOf('dabwali') !== -1 || t.indexOf('dabwali') !== -1) {
          sel.selectedIndex = j;
          // Fire change event so downstream logic runs (locality load etc.)
          try { sel.dispatchEvent(new Event('change', { bubbles: true })); } catch(_){}
          break;
        }
      }
    }
  }

  // 2. Nuke text nodes containing "Sirsa · Bathinda · Mansa · Muktsar" patterns
  var CITY_RE = /(·\s*(Sirsa|Bathinda|Mansa|Muktsar|Sri Muktsar Sahib|Malout|Gidderbaha|Hanumangarh|Rania|Ellenabad|Kalanwali|Fatehabad|Sri Ganganagar))+/gi;
  var CITY_LIST_RE = /Sirsa\s*[·,]\s*Bathinda\s*[·,]\s*Mansa\s*[·,]\s*Muktsar/gi;

  function nukeCityText(root){
    if (!root) root = document.body;
    if (!root) return;
    var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null, false);
    var toReplace = [];
    var n;
    while ((n = walker.nextNode())) {
      var t = n.nodeValue;
      if (!t) continue;
      if (CITY_LIST_RE.test(t) || CITY_RE.test(t)) {
        var newT = t.replace(CITY_LIST_RE, 'Mandi Dabwali').replace(CITY_RE, '');
        if (newT !== t) toReplace.push([n, newT]);
      }
      CITY_LIST_RE.lastIndex = 0;
      CITY_RE.lastIndex = 0;
    }
    toReplace.forEach(function(pair){ pair[0].nodeValue = pair[1]; });
  }

  // 3. Hide the 📍 area chip on business.html (redundant since all Dabwali)
  function hideBizLocation(){
    var ids = ['premAreaChip', 'premCityChip', 'premLocationChip', 'bizCityChip'];
    ids.forEach(function(id){
      var el = document.getElementById(id);
      if (el) el.style.display = 'none';
    });
  }

  function run(){
    try { forceCityDabwali(); } catch(e){ console.warn(TAG, 'city sel', e); }
    try { hideBizLocation(); } catch(e){ console.warn(TAG, 'biz loc', e); }
    try { nukeCityText(document.body); } catch(e){ console.warn(TAG, 'text', e); }
  }

  if (document.readyState !== 'loading') run();
  document.addEventListener('DOMContentLoaded', run);
  window.addEventListener('load', function(){ setTimeout(run, 400); });

  // Watch for late renders
  if (window.MutationObserver) {
    var obsCount = 0;
    var obs = new MutationObserver(function(){
      if (obsCount++ > 30) { obs.disconnect(); return; }
      run();
    });
    if (document.body) obs.observe(document.body, { childList: true, subtree: true });
    else document.addEventListener('DOMContentLoaded', function(){
      obs.observe(document.body, { childList: true, subtree: true });
    });
  }
})();

